<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {NCard,NButton,NInput,NSelect,NAlert,NStatistic,NTag} from 'naive-ui'
import {api,uncertainMessage} from '../../api'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
import PlayerShortcuts from '../../components/PlayerShortcuts.vue'
import DnfBackdrop from '../../components/DnfBackdrop.vue'
const gm=useGmWorkspace(),router=useRouter(),query=ref(''),mode=ref('account'),cases=ref<any[]>([]),caseError=ref('')
const modes=[{label:'账号 / UID',value:'account'},{label:'角色名 / 编号',value:'role'}]
let alive=true
function search(){void router.push({path:'/players',query:{q:query.value,mode:mode.value}})}
function openTarget(value:{uid:number,charac_no:number}){void router.push(value.charac_no?'/characters/'+value.charac_no:'/players/'+value.uid)}
onMounted(async()=>{void gm.activate('overview');try{const result=await api('/support/cases?uid=0&page=1&status=open&category=&q=');if(alive)cases.value=result.items||[]}catch(e){if(alive)caseError.value=uncertainMessage(e)}})
onUnmounted(()=>alive=false)
</script>
<template><div class="gm-workspace player-home"><NCard class="player-search-card" :bordered="false"><DnfBackdrop/><div class="home-heading"><div><NTag type="primary" size="small" round>玩家工作台</NTag><h1>今天要帮助哪位玩家？</h1><p>查找账号或角色，查看存档、处理问题与组合奖励。</p></div><NButton secondary @click="gm.go('catalog')">浏览物品目录</NButton></div><form class="home-player-search" @submit.prevent="search"><NSelect v-model:value="mode" :options="modes" aria-label="搜索类型"/><NInput v-model:value="query" clearable size="large" :placeholder="mode==='role'?'角色名或角色编号':'账号名或 UID'" aria-label="查找玩家"/><NButton type="primary" size="large" attr-type="submit">查找玩家</NButton></form></NCard>
 <PlayerShortcuts :revision="gm.playerRevision" :busy="gm.busy||!!gm.pendingId" :current="gm.currentPlayerTarget" default-expanded @choose="openTarget" @changed="gm.playerRevision++" @expired="gm.clearSession"/>
 <div class="home-work-grid"><NCard title="待处理问题" :bordered="false"><template #header-extra><NButton text type="primary" @click="gm.go('support')">全部问题 →</NButton></template><NAlert v-if="caseError" type="warning" :show-icon="false">{{caseError}}</NAlert><div v-else-if="cases.length" class="home-cases"><button v-for="item in cases.slice(0,4)" :key="item.case_id" @click="gm.supportUid=item.uid;gm.go('support')"><strong>{{item.title}}</strong><small>{{item.target?.accountname||'玩家'}} · UID {{item.uid}} · 已关联 {{item.compensation_count||0}} 笔补偿</small></button></div><p v-else class="muted">当前没有待处理问题。</p></NCard>
 <NCard title="操作核对" :bordered="false"><NAlert v-if="gm.pendingId" type="warning" title="上一笔提交结果待确认"><code>{{gm.pendingId}}</code><p>保留原编号查询，先核对再创建下一笔操作。</p><NButton size="small" @click="gm.inspectOperation(gm.pendingId)">查询原操作</NButton></NAlert><p v-else class="muted">当前会话没有普通奖励提交待核对。</p><div class="home-actions"><NButton secondary @click="gm.go('audit')">操作审计与原编号查询</NButton><NButton secondary @click="gm.go('reward-jobs')">批量任务</NButton><NButton secondary @click="gm.go('maintenance')">维护与恢复</NButton></div></NCard></div>
 <div v-if="gm.overview" class="home-server-summary"><NCard :bordered="false"><NStatistic label="注册账号" :value="gm.overview.counts?.accounts??'—'"/></NCard><NCard :bordered="false"><NStatistic label="游戏角色" :value="gm.overview.counts?.characters??'—'"/></NCard><NCard :bordered="false"><NStatistic label="登录状态表在线" :value="gm.overview.counts?.online_accounts??'—'"/></NCard><NCard :bordered="false"><small>服务器状态</small><h3>{{gm.overview.server?.fresh?'快照有效':'状态未知'}}</h3><NButton text type="primary" @click="gm.go('operations-dashboard')">查看资源与诊断 →</NButton></NCard></div>
</div></template>
<style scoped>.player-search-card{position:relative;overflow:hidden}.player-search-card :deep(.n-card__content){position:relative}.home-heading,.home-player-search{position:relative;z-index:1}.player-home{display:grid;gap:20px}.home-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.home-heading h1{font-size:27px;line-height:1.35;margin:14px 0 8px;color:var(--text-primary)}.home-heading p{color:var(--text-secondary)}.home-player-search{display:grid;grid-template-columns:150px minmax(0,1fr) auto;gap:12px;margin-top:24px}.home-work-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:20px}.home-cases{display:grid;gap:10px}.home-cases>button{display:grid;gap:6px;text-align:left;padding:12px;border:1px solid var(--border-color);border-radius:10px}.home-cases small{color:var(--text-secondary)}.home-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.home-server-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.home-server-summary h3{margin:8px 0}.player-home :deep(.n-card){border-radius:16px}@media(max-width:800px){.home-work-grid{grid-template-columns:1fr}.home-server-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.home-heading{align-items:start}.home-heading h1{font-size:23px}.home-heading>.n-button{display:none}}@media(max-width:500px){.home-player-search{grid-template-columns:1fr auto}.home-player-search>.n-select{grid-column:1/-1}.home-heading h1{font-size:21px}.player-home{gap:14px}.home-server-summary{gap:10px}}</style>

